local str1 = "__framework__"
local var1 = require(script.Parent.Parent.Parent:WaitForChild(str1))
local tbl1 = { Luck = 115499696950998, Coin = 81018174833942 }
local function coin(arg1, arg2)
	return {
		Time = arg1,
		Reward = { Type = "Coin", Icon = 81018174833942, Seconds = arg2 },
		Handler = function(arg1)
			local var2 = var1.getDependencies()
			local var4 = math.floor((var2.TimeskipService:CalcuteRewards(arg1, arg2, true)))
			if var4 <= 0 then
				return
			end

			var2.PlayerDataService:GetAccountAsync(arg1):andThen(function(arg1)
				arg1.Replica.Profile:Write("GiveStat", "Coin", var4, "TimedReward", "Playtime")
			end)
		end,
	}
end

local function boost(arg1, arg2, arg3, arg4, arg5)
	return {
		Time = arg1,
		Reward = { Type = "Boost", Icon = tbl1[arg2], DisplayName = arg5 },
		Handler = function(arg1)
			var1.getDependencies().BoostService:Give(arg1, arg2, arg3, arg4)
		end,
	}
end

str1 = function(arg1, arg2, arg3, arg4)
	return {
		Time = arg1,
		Reward = { Type = "Timeskip", Icon = 88809757782495, DisplayName = arg4 },
		Handler = function(arg1)
			var1.getDependencies().TimeskipService:Give(arg1, arg2, arg3)
		end,
	}
end

return {
	coin(60, 15),
	coin(180, 20),
	coin(300, 30),
